cards.name:
[[[
  if (window.location.href.includes("cameras-detail") || window.location.href.includes("gate-detail")) {
    return "";
  }
  const entities = [
    "input_boolean.play_front_cruiser_2",
    "input_boolean.play_garden_zoom",
    "input_boolean.play_garden_wide",
    "input_boolean.play_g5_garage",
    "input_boolean.play_corridor_cam",
    "input_boolean.play_stair_cam",
    "input_boolean.play_mezzanine_cam"
  ];
  window.lastHass = hass;
  console.log("Invisible stop card (main) evaluated!");

  const stopAll = () => {
    const h = window.lastHass || hass;
    if (!h) return;
    console.log("stopAll (main) triggered, turning off entities:", entities);
    entities.forEach(ent => {
      if (h.states[ent] && h.states[ent].state === "on") {
        h.callService("input_boolean", "turn_off", {
          entity_id: ent
        });
      }
    });
  };

  // stopAll(); <-- Removed unconditional execution to prevent rapid toggling loop

  if (!window.locationObserverActive) {
    window.locationObserverActive = true;
    window.lastObservedUrl = window.location.href;
    console.log("URL observer started. Current URL:", window.location.href);
    setInterval(() => {
      const currentUrl = window.location.href;
      if (currentUrl !== window.lastObservedUrl) {
        console.log("URL change detected:", window.lastObservedUrl, "->", currentUrl);
        window.lastObservedUrl = currentUrl;
        stopAll();
      }
    }, 2000);
  }

  if (!window.stopCamerasListenerAdded) {
    window.stopCamerasListenerAdded = true;
    console.log("Visibility listeners added.");
    document.addEventListener("visibilitychange", () => {
      console.log("visibilitychange event, state:", document.visibilityState);
      if (document.visibilityState === "hidden") {
        stopAll();
      }
    });
    window.addEventListener("pagehide", () => {
      console.log("pagehide event");
      stopAll();
    });
  }
  return "";
]]]

